\begin{proof}
We begin by introducing some notation that we will use throughout the proof.
Let $\tau \in \{0, 1\}^k$ be a type.
Then we define
\begin{equation*}
\tau_{< \ell}  = (\tau_1, \ldots, \tau_{\ell-1}) \in \{0, 1\}^{\ell-1}\;,
\quad
\tau_{> \ell}  = (\tau_{\ell+1}, \ldots, \tau_{k}) \in \{0,1\}^{k-\ell}\;,
\end{equation*}
and we define $\tau_{\leq \ell}$ and $\tau_{\geq \ell}$ similarly.
In addition, given $(g_1, \ldots, g_k) \in (\code^+)^{k}$, we define
\begin{equation*}
g_{< \ell}  = (g_1, \ldots, g_{\ell-1})\;,
\qquad
g_{> \ell}  = (g_{\ell+1}, \ldots, g_{k})
\end{equation*}
and we define $g_{\leq \ell}$ and $g_{\geq \ell}$ similarly.
Using this notation, we can write
\begin{equation*}
 \wH^{x_{\geq \ell}}_{g_{\geq \ell}} = \wH^{x_{\ell}, \ldots, x_k}_{g_{\ell}, \ldots, g_k}\;.
\end{equation*}
Next, we introduce the notation
\begin{equation*}
\wG^{x_{\geq \ell}}_{g_{\geq \ell}} = \wG^{x_{\ell}}_{g_{\ell}} \cdots \wG^{x_k}_{g_k}\;.
\end{equation*}
This satisfies the recurrence relation
\begin{equation}\label{eq:G-recurrence}
\wG^{x_{\geq \ell}}_{g_{\geq \ell}} = \wG^{x_{\ell}}_{g_{\ell}} \cdot \wG^{x_{> \ell}}_{g_{> \ell}}\;.
\end{equation}
Furthermore, we can write
\begin{equation}\label{eq:split-H-into-two-Gs}
 \wH^{x_{\geq \ell}}_{g_{\geq \ell}} = (\wG^{x_{\geq \ell}}_{g_{\geq \ell}}) \cdot (\wG^{x_{\geq \ell}}_{g_{\geq \ell}})^\dagger.
\end{equation}

To prove the lemma we show that for each $1 \leq \ell \leq k$,
\begin{align}
&\E_{x_{\geq \ell}} \sum_{\tau:|\tau| \geq t}  \sum_{g_{\geq \ell} \in \outc_{\tau_{\geq \ell}}}
	\tau\big(\widehat{H}^{x_{\geq \ell}}_{g_{\geq \ell}} \cdot (G^{|\tau_{<\ell}|}\cdot (\id - G)^{(\ell-1)-|\tau_{<\ell}|}) \big)\nonumber\\
\approx_{2k\nu'_2}~&\E_{x_{>\ell}} \sum_{\tau:|\tau| \geq t} \sum_{g_{> \ell} \in \outc_{\tau_{> \ell}}}
	\tau\big(\widehat{H}^{x_{> \ell}}_{g_{> \ell}} \cdot (G^{|\tau_{\leq \ell}|} \cdot (\id - G)^{\ell-|\tau_{\leq\ell}|}) \big)\;.
	\label{eq:i-think-this-is-what-i'm-supposed-to-prove}
\end{align}
If we then repeatedly apply \Cref{eq:i-think-this-is-what-i'm-supposed-to-prove} for $\ell = 1, \ldots, k$,
we derive
\begin{align*}
&\E_{x_1, \dots, x_k} \sum_{\tau:|\tau| \geq t} 
	\sum_{(g_1, \ldots, g_{k}) \in \outc_{\tau}} \tau\big(\widehat{H}^{x_1, \dots, x_k}_{g_1, \dots, g_k} \big)\\
=~&\E_{x_{\geq 1}} \sum_{\tau:|\tau| \geq t} 
	\sum_{g_{\geq 1} \in \outc_{\tau}} \tau\big(\widehat{H}^{x_{\geq 1}}_{g_{\geq 1}} \big)\\
\approx_{2k\nu'_2}~&\E_{x_{\geq 2}} \sum_{\tau:|\tau| \geq t} 
	\sum_{g_{\geq 2} \in \outc_{\tau_{\geq 2}}} \tau\big(\widehat{H}^{x_{\geq 2}}_{g_{\geq 2}} \cdot (G^{|\tau_{\leq 1}|} \cdot (\id - G)^{1-|\tau_{\leq1}|}) \big)\\
\approx_{2k\nu'_2}~&\E_{x_{\geq 3}} \sum_{\tau:|\tau| \geq d+1} 
	\sum_{g_{\geq 3} \in \outc_{\tau_{\geq 3}}} \tau\big(\widehat{H}^{x_{\geq 3}}_{g_{\geq 3}} \cdot (G^{|\tau_{\leq 2}|} \cdot (\id - G)^{2-|\tau_{\leq2}|}) \big)\\
	\cdots&\\
\approx_{2k\nu'_2}~& \sum_{\tau:|\tau| \geq t} 
	 \tau \big(G^{|\tau|} \cdot (\id - G)^{k-|\tau|} \big)\\
=~&\sum_{i = t}^k \binom{k}{i} \tau\big(G^i (\id - G)^{k-i}  \big)\;.
\end{align*}
This proves the lemma.

We now prove \Cref{eq:i-think-this-is-what-i'm-supposed-to-prove}.
To begin, for each $1 \leq \ell \leq k+1$ and $\tau_{\geq \ell} \in \{0, 1\}^{k - \ell + 1}$,
we define the operator
\begin{equation}\label{eq:S-def}
S_{\tau_{\geq \ell}} = \sum_{\tau_{< \ell} : |\tau| \geq t} G^{|\tau_{<\ell}|}\cdot (\id - G)^{(\ell-1)-|\tau_{<\ell}|}\;.
\end{equation}
Then the statement in \Cref{eq:i-think-this-is-what-i'm-supposed-to-prove} can be rewritten as
\begin{align}
&\E_{x_{\geq \ell}} \sum_{\tau_{\geq \ell}}  \sum_{g_{\geq \ell} \in \outc_{\tau_{\geq \ell}}}
	\tau\big(\widehat{H}^{x_{\geq \ell}}_{g_{\geq \ell}} \cdot S_{\tau_{\geq \ell}}\big)\nonumber\\
\approx_{2k\nu'_2}~&\E_{x_{> \ell}} \sum_{\tau_{>\ell}} \sum_{g_{>\ell} \in \outc_{\tau_{> \ell}}}
	\tau\big(\widehat{H}^{x_{>\ell}}_{g_{>\ell}} \cdot S_{\tau_{>\ell}} \big)\;.
	\label{eq:i-think-this-is-what-i'm-supposed-to-prove-2}
\end{align}
To prove this, we will use several facts about $S_{\tau_{\geq \ell}}$.
First, $S$ is self-adjoint and positive semidefinite.
This is because each term in \Cref{eq:S-def}
is a product of~$G$ and $(\id - G)$.
These operators commute with each other,
and both are self-adjoint and positive semidefinite.
Next, $S$ is bounded:
\begin{align}
S_{\tau_{\geq \ell}}
&= \sum_{\tau_{< \ell} : |\tau| \geq t} G^{|\tau_{<\ell}|}\cdot (\id - G)^{(\ell-1)-|\tau_{<\ell}|}\nonumber\\
&\leq \sum_{\tau_{< \ell} } G^{|\tau_{<\ell}|}\cdot (\id - G)^{(\ell-1)-|\tau_{<\ell}|}\nonumber\\
& = (G + (\id - G))^{\ell-1}\nonumber\\
& = \id\;. \label{eq:S-bound}
\end{align}
In addition, for any $\tau_{\ell} \in \{0, 1\}$,
\begin{align}
\Big(\E_{x_{\ell}} \sum_{g_{\ell} \in \outc_{\tau_{\ell}}} \wG^{x_{\ell}}_{g_{\ell}}\Big)
& = \left\{ \begin{array}{cl}
		G & \text{if } \tau_{\ell} = 1\;,\\
		(\id - G) & \text{if } \tau_{\ell} = 0\;,
	\end{array}\right.\nonumber\\
&= G^{\tau_{\ell}} \cdot (\id - G)^{1 - \tau_{\ell}}\;.\label{eq:explicit-formula-for-G-expectation}
\end{align}
Thus, for any $\tau_{> \ell}$,
\begin{align}
\sum_{\tau_{\ell}} 
	S_{\tau_{\geq \ell}} \cdot \Big(\E_{x_{\ell}} \sum_{g_{\ell} \in \outc_{\tau_{\ell}}} \wG^{x_{\ell}}_{g_{\ell}}\Big)
&= \sum_{\tau_{\ell}}  S_{\tau_{\geq \ell}} \cdot(G^{\tau_{\ell}} \cdot (\id - G)^{1 - \tau_{\ell}})\nonumber\\
&= \sum_{\tau_{\ell}}  \sum_{\tau_{< \ell} : |\tau| \geq t} G^{|\tau_{<\ell}|}\cdot (\id - G)^{(\ell-1)-|\tau_{<\ell}|}
	\cdot (G^{\tau_{\ell}} \cdot (\id - G)^{1 - \tau_{\ell}})\nonumber\\
&= \sum_{\tau_{\ell}}  \sum_{\tau_{< \ell} : |\tau| \geq t} G^{|\tau_{\leq \ell}|}\cdot (\id - G)^{\ell-|\tau_{\leq\ell}|}\nonumber\\
&= \sum_{\tau_{\leq \ell} : |\tau| \geq t} G^{|\tau_{\leq \ell}|}\cdot (\id - G)^{\ell-|\tau_{\leq\ell}|}\nonumber\\
&= S_{\tau_{> \ell}}\;.\label{eq:S-recurrence}
\end{align}
Finally, for any $\tau_{\geq \ell}$,
\begin{align}
&S_{\tau_{\geq \ell}}
	\cdot \Big(\E_{x_{\ell}} \sum_{g_{\ell} \in \outc_{\tau_{\ell}}} \wG^{x_{\ell}}_{g_{\ell}}\Big)
	\cdot S_{\tau_{\geq \ell}}\nonumber\\
 =~& S_{\tau_{\geq \ell}}
	\cdot (G^{\tau_{\ell}} \cdot (\id - G)^{1 - \tau_{\ell}})
	\cdot S_{\tau_{\geq \ell}} \tag{by \Cref{eq:explicit-formula-for-G-expectation}}\\
 =~& \sqrt{G^{\tau_{\ell}} \cdot (\id - G)^{1 - \tau_{\ell}}} \cdot (S_{\tau_{\geq \ell}})^2
	\cdot \sqrt{G^{\tau_{\ell}} \cdot (\id - G)^{1 - \tau_{\ell}}}\tag{because $S_{\tau_{\geq \ell}}$ commutes with $G$ and $(\id - G)$}\\
\leq~& \sqrt{G^{\tau_{\ell}} \cdot (\id -  G)^{1 - \tau_{\ell}}} \cdot I
	\cdot \sqrt{G^{\tau_{\ell}} \cdot (\id -  G)^{1 - \tau_{\ell}}} \tag{by \Cref{eq:S-bound}}\\
=~& G^{\tau_{\ell}} \cdot (\id -  G)^{1 - \tau_{\ell}}\nonumber\\
=~& \Big(\E_{x_{\ell}} \sum_{g_{\ell} \in \outc_{\tau_{\ell}}} \wG^{x_{\ell}}_{g_{\ell}}\Big)\;, \label{eq:S-sandwich}
\end{align}
where the last step uses \Cref{eq:explicit-formula-for-G-expectation} again.
This concludes the set of facts we will need about $S_{\tau_{\geq \ell}}$.

Now we prove \Cref{eq:i-think-this-is-what-i'm-supposed-to-prove-2}.
To start, we write using the definition
\begin{align}
&\E_{x_{\geq \ell}} \sum_{\tau_{\geq \ell}}  \sum_{(g_{\ell}, \ldots,g_k) \in \outc_{\tau_{\geq \ell}}}
	\tau\big(\widehat{H}^{x_{\ell}, \dots, x_{k}}_{g_{\ell}, \dots, g_{k}} \cdot S_{\tau_{\geq \ell}}\big)\nonumber\\
=~&\E_{x_{\geq \ell}} \sum_{\tau_{\geq \ell}}  \sum_{(g_{\ell}, \ldots,g_k) \in \outc_{\tau_{\geq \ell}}}
	\tau\big(\wG^{x_{\ell}}_{g_{\ell}}\cdot (\wG^{x_{> \ell}}_{g_{> \ell}} \cdot (\wG^{x_{> \ell}}_{g_{> \ell}})^\dagger) \cdot  \wG^{x_{\ell}}_{g_{\ell}}\cdot S_{\tau_{\geq \ell}} \big)\;.\label{eq:move-g-over-there}
\end{align}
Next, we commute the leftmost $\wG^{x_{\ell}}_{g_{\ell}}$ to the right. Using \Cref{cor:G-hat-facts} and \Cref{lem:switcheroo} we get
\[ \wG^{x_{\ell}}_{g_{\ell}}\cdot \wG^{x_{> \ell}}_{g_{> \ell}} \approx_{k\nu'_2}  \wG^{x_{> \ell}}_{g_{> \ell}}\cdot \wG^{x_{\ell}}_{g_{\ell}}\]
and similarly 
\[ \wG^{x_{\ell}}_{g_{\ell}}\cdot (\wG^{x_{> \ell}}_{g_{> \ell}})^\dagger \approx_{k\nu'_2}  (\wG^{x_{> \ell}}_{g_{> \ell}})^\dagger \cdot \wG^{x_{\ell}}_{g_{\ell}}\;.\]
Combining with \Cref{lem:closeness-to-close-ips} and injecting back into~\eqref{eq:move-g-over-there} we get
\begin{equation}\label{eq:move-g-over-there-2}
\E_{x_{\geq \ell}} \sum_{\tau_{\geq \ell}}  \sum_{(g_{\ell}, \ldots,g_k) \in \outc_{\tau_{\geq \ell}}}
	\tau\big(\widehat{H}^{x_{\ell}, \dots, x_{k}}_{g_{\ell}, \dots, g_{k}} \cdot S_{\tau_{\geq \ell}}\big)
	\approx_{2k\nu'_2} \E_{x_{\geq \ell}} \sum_{\tau_{\geq \ell}}  \sum_{(g_{\ell}, \ldots,g_k) \in \outc_{\tau_{\geq \ell}}}
	\tau\big((\wG^{x_{> \ell}}_{g_{> \ell}} \cdot (\wG^{x_{> \ell}}_{g_{> \ell}})^\dagger) \cdot  \wG^{x_{\ell}}_{g_{\ell}}\cdot S_{\tau_{\geq \ell}} \big)\;.
\end{equation}
We end by noting that
\begin{align*}
\eqref{eq:move-g-over-there-2}
& =
\E_{x_{\geq \ell}} \sum_{\tau_{\geq \ell}}  \sum_{(g_{\ell}, g_{>\ell}) \in \outc_{\tau_{\geq \ell}}}
	\tau\big(\wH^{x_{> \ell}}_{g_{> \ell}} \cdot (S_{\tau_{\geq \ell}} \cdot \wG^{x_{\ell}}_{g_{\ell}})\big)\\
& =\E_{x_{> \ell}} \sum_{\tau_{> \ell}}  \sum_{g_{>\ell} \in \outc_{\tau_{> \ell}}}
	\tau\big(\wH^{x_{> \ell}}_{g_{> \ell}} \cdot \Big(\sum_{\tau_{\ell}}S_{\tau_{\geq \ell}} \cdot
		\Big(\E_{x_{\ell}} \sum_{g_\ell \in \outc_{\tau_{\ell}}}\wG^{x_{\ell}}_{g_{\ell}}\Big)\Big)\big)\\
& =\E_{x_{> \ell}} \sum_{\tau_{> \ell}}  \sum_{g_{>\ell} \in \outc_{\tau_{> \ell}}}
	\tau\big(\wH^{x_{> \ell}}_{g_{> \ell}} \cdot S_{\tau_{>\ell}}\big)\;. \tag{by \Cref{eq:S-recurrence}}
\end{align*}
This concludes the proof of
\Cref{eq:i-think-this-is-what-i'm-supposed-to-prove-2}
and therefore proves the lemma.
\end{proof}
